class Solution {
  public int[][] constructGridLayout(int n, int[][] edges) {
    int[] deg = new int[n + 1];
    for (int[] e : edges) {
      deg[e[0]]++;
      deg[e[1]]++;
    }
    int[] start = new int[n + 1];
    for (int i = 0; i < n; i++) start[i + 1] = start[i] + deg[i];
    int[] adj = new int[2 * edges.length], pos = new int[n];
    for (int[] e : edges) {
      adj[start[e[0]] + pos[e[0]]++] = e[1];
      adj[start[e[1]] + pos[e[1]]++] = e[0];
    }
    int corner = -1;
    for (int i = 0; i < n; i++) {
      if (deg[i] == 1) {
        corner = i;
        break;
      }
      if (deg[i] == 2 && corner < 0) corner = i;
    }
    boolean path = deg[corner] == 1;
    boolean[] seen = new boolean[n];
    int[] row = new int[n];
    int len = 0, cur = corner;
    seen[cur] = true;
    row[len++] = cur;
    while (true) {
      if (len > 1 && !path && deg[cur] == 2) break;
      int next = -1;
      for (int p = start[cur]; p < start[cur + 1]; p++) {
        int v = adj[p];
        if (!seen[v] && (next < 0 || deg[v] < deg[next])) next = v;
      }
      if (next < 0) break;
      seen[next] = true;
      row[len++] = next;
      cur = next;
    }
    int rows = n / len;
    int[][] grid = new int[rows][len];
    System.arraycopy(row, 0, grid[0], 0, len);
    for (int r = 1; r < rows; r++) {
      for (int j = 0; j < len; j++) {
        int u = grid[r - 1][j];
        for (int p = start[u]; p < start[u + 1]; p++) {
          if (!seen[adj[p]]) {
            grid[r][j] = adj[p];
            seen[adj[p]] = true;
            break;
          }
        }
      }
    }
    return grid;
  }
}
